index 77470f8..61c7996 100644
--- a/src/session-store.ts
+++ b/src/session-store.ts
@@ -1,3 +1,4 @@
+import { createHmac } from "crypto";
 import { pool } from "./pool.ts";

 export interface Session {
@@ -6,16 +7,59 @@ export interface Session {
   revokedAt: Date | null;
 }

-export const loadSession = async (id: string): Promise<Session | null> => {
+const getSigningKey = (): string => {
+  const key = process.env.SESSION_SIGNING_KEY;
+  if (!key) {
+    throw new Error("SESSION_SIGNING_KEY environment variable is not set");
+  }
+  return key;
+};
+
+export const signToken = (sessionId: string): string => {
+  const key = getSigningKey();
+  const signature = createHmac("sha256", key)
+    .update(sessionId)
+    .digest("base64url");
+  return `${sessionId}.${signature}`;
+};
+
+export const validateTokenSignature = (token: string): string | null => {
+  const [sessionId, signature] = token.split(".");
+  if (!sessionId || !signature) return null;
+
+  const key = getSigningKey();
+  const expectedSignature = createHmac("sha256", key)
+    .update(sessionId)
+    .digest("base64url");
+
+  if (signature !== expectedSignature) return null;
+  return sessionId;
+};
+
+export const loadSession = async (
+  tokenOrId: string,
+): Promise<Session | null> => {
+  let sessionId = tokenOrId;
+
+  if (tokenOrId.includes(".")) {
+    const validated = validateTokenSignature(tokenOrId);
+    if (!validated) return null;
+    sessionId = validated;
+  }
+
   const result = await pool.query(
     "SELECT id, user_id, revoked_at FROM sessions WHERE id = $1",
-    [id],
+    [sessionId],
   );
   const row = result.rows[0];
   if (row === undefined || row.revoked_at !== null) return null;
   return { id: row.id, userId: row.user_id, revokedAt: row.revoked_at };
 };

+export const loadSessionFromEdge = (token: string): string | null => {
+  return validateTokenSignature(token);
+};
+
 export const revokeSession = async (id: string): Promise<void> => {
   await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [id]);
 };
